:         expected = expected + values[:, column]\n57:     actual = output.detach().cpu().numpy().astype(np.float64)\n58:     error = float(np.linalg.norm(actual - expected) / max(np.linalg.norm(expected), 1e-12))\n59:     structural = (tuple(output.shape) == (4,) and output.dtype == torch.float32\n60:                   and bool(np.isfinite(actual).all()) and bool(torch.equal(x, before)))\n61:     return {\"reference_method\": \"sequential float64 accumulation in row order\",\n62:             \"reference\": expected.tolist(), \"output\": actual.tolist(),\n63:             \"relative_error\": error, \"tolerance\": 1e-5,\n64:             \"shape_dtype_finite_and_inputs_unmodified\": structural,\n65:             \"passed\": bool(structural and error <= 1e-5)}",
